<?php
namespace Agah\Erp\Http;
use Agah\Erp\Core\{Ctx,Money,Jalali,Request,FiscalContext};
use Agah\Erp\Modules\Manufacturing\ProductionService;
if(!defined('ABSPATH'))exit;
$o=ProductionService::order($cid,Request::int('get','id'));$snap=json_decode($o['snapshot'],true);$draft=$o['status']==='draft';
?>
<section class="erp-card erp-print-document erp-production-document"><h2>دستور تولید <?php echo esc_html(Money::toFa($o['number'])); ?></h2><dl class="erp-metadata"><dt>محصول</dt><dd><?php echo esc_html(($snap['product_code']??'').' — '.($snap['product_name']??'')); ?></dd><dt>فرمول / نسخه</dt><dd><?php echo esc_html(($snap['bom']['name']??'').' / '.$o['bom_revision']); ?></dd><dt>مقدار برنامه</dt><dd><?php echo esc_html(Money::qtyToDb((int)$o['planned_qty']).' '.($snap['unit_name']??'')); ?></dd><dt>وضعیت</dt><dd><?php echo esc_html(ProductionService::STATES[$o['status']]??$o['status']); ?></dd><dt>تاریخ دستور / شروع / تکمیل</dt><dd><?php echo esc_html(Jalali::format($o['doc_date']).' / '.($o['start_date']?Jalali::format($o['start_date']):'—').' / '.($o['finish_date']?Jalali::format($o['finish_date']):'—')); ?></dd></dl>
<?php if($draft&&Ctx::can('production.approve')): ?><form method="post" class="erp-form"><?php self::form('module_production_start',$cid,'production_order',$o['id']); ?><input type="hidden" name="revision" value="<?php echo (int)$o['revision']; ?>"><?php self::input('start_date','تاریخ شروع تولید',Jalali::format(max($o['doc_date'],FiscalContext::today($cid)),false),'text','required data-jalali dir="ltr"');self::input('reason','دلیل انحراف از مقدار برنامه (در صورت تغییر)','','text','maxlength="300"'); ?><?php endif; ?>
<div class="erp-trade-wide"><div class="erp-scroll erp-entry-scroll" tabindex="0" aria-label="مصرف مواد دستور تولید"><table class="erp-table erp-lines"><colgroup><col style="width:32%"><col style="width:16%"><col style="width:18%"><col style="width:18%"><col style="width:16%"></colgroup><thead><tr><th>ماده اولیه / واحد</th><th>انبار</th><th>نیاز برنامه</th><th>مصرف واقعی</th><th>بهای واقعی</th></tr></thead><tbody><?php $old=self::value('materials',[]);foreach($o['lines'] as $l): ?><tr><td><?php echo esc_html($l['item_code'].' — '.$l['item_name'].' / '.$l['unit_name']); ?></td><td><?php echo esc_html(\Agah\Erp\Core\Db::val('SELECT name FROM '.\Agah\Erp\Core\Db::t('warehouses').' WHERE company_id=%d AND id=%d',$cid,$l['warehouse_id'])); ?></td><td><?php echo esc_html(Money::qtyToDb((int)$l['planned_qty'])); ?></td><td><?php if($draft&&Ctx::can('production.approve')): ?><input name="materials[<?php echo (int)$l['id']; ?>][qty]" value="<?php echo esc_attr($old[$l['id']]['qty']??Money::qtyToDb((int)$l['planned_qty'])); ?>" inputmode="decimal" aria-label="مصرف واقعی ماده" required><?php else:echo esc_html(Money::qtyToDb((int)$l['actual_qty']));endif; ?></td><td><?php echo esc_html(Money::fmt((int)$l['cost'],Ctx::unit())); ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php if($draft&&Ctx::can('production.approve')): ?><p>شروع تولید موجودی مواد را کم می‌کند. کمبود موجودی یا دوره بسته، کل عملیات را بدون ثبت ناقص متوقف می‌کند.</p><button type="submit" class="btn btn-primary">شروع تولید و مصرف مواد</button></form><?php endif; ?>
<?php if(!$draft): ?><div class="erp-stats"><?php foreach(['material_cost'=>'مواد مصرفی','labor_cost'=>'دستمزد جذب‌شده','overhead_cost'=>'سربار جذب‌شده','abnormal_cost'=>'هزینه ضایعات غیرعادی','total_cost'=>'بهای محصول تولیدشده'] as $key=>$label): ?><div><span><?php echo esc_html($label); ?></span><strong><?php echo esc_html(Money::fmt((int)$o[$key],Ctx::unit())); ?></strong></div><?php endforeach; ?></div><p>محصول سالم: <?php echo esc_html(Money::qtyToDb((int)$o['actual_qty'])); ?> | محصول مردود: <?php echo esc_html(Money::qtyToDb((int)$o['scrap_qty'])); ?></p><?php if($o['actual_qty']): ?><p>بهای واحد (گردشده برای نمایش): <?php try{echo esc_html(Money::fmt(Money::mulDiv((int)$o['total_cost'],10000,(int)$o['actual_qty']),Ctx::unit()));}catch(\InvalidArgumentException $e){echo 'خارج از محدوده نمایش واحد؛ مبلغ کل معتبر در بالا نمایش داده شده است.';} ?></p><?php endif; ?><p><?php echo esc_html($o['variance_reason']); ?></p><?php endif; ?>
<p><?php echo esc_html($o['description']); ?></p><p class="erp-no-print"><?php foreach(['start_voucher_id'=>'سند مصرف مواد','finish_voucher_id'=>'سند تکمیل تولید'] as $key=>$label)if($o[$key]&&Ctx::can('voucher.view'))echo '<a class="btn btn-outline" href="'.esc_url(agah_erp_url(['c'=>$cid,'p'=>'voucher_view','id'=>$o[$key]])).'">'.esc_html($label).'</a> '; ?><button type="button" class="btn btn-outline" data-print>چاپ دستور تولید</button></p></section>
<?php if($draft&&Ctx::can('production.edit')): ?><section class="erp-card erp-no-print"><details><summary>ویرایش برنامه و بازسازی مواد پیش‌نویس</summary><p>ذخیره این فرم، نیاز مواد را از نسخه فعلی فرمول انتخابی دوباره محاسبه می‌کند.</p><?php require __DIR__.'/production-plan-edit.php'; ?></details></section><?php endif; ?>
<?php if($o['status']==='running'&&Ctx::can('production.approve')): ?>
<section class="erp-card erp-no-print"><h3>تکمیل تولید و رسید محصول</h3><p>واحد هزینه‌ها: <?php echo Ctx::unit()==='rial'?'ریال':'تومان'; ?>. دستمزد و سربار از هزینه‌های ثبت‌شده به محصول منتقل می‌شوند؛ پرداخت دوباره ثبت نمی‌شود. ضایعات عادی در بهای محصول سالم جذب و هزینه ضایعات غیرعادی جداگانه هزینه می‌شود.</p><form method="post" class="erp-form"><?php self::form('module_production_complete',$cid,'production_order',$o['id']); ?><input type="hidden" name="revision" value="<?php echo (int)$o['revision']; ?>"><?php self::input('finish_date','تاریخ تکمیل',Jalali::format(max($o['start_date'],FiscalContext::today($cid)),false),'text','required data-jalali dir="ltr"');self::input('actual_qty','مقدار محصول سالم',Money::qtyToDb((int)$o['planned_qty']),'text','required inputmode="decimal"');self::input('scrap_qty','مقدار محصول مردود','0','text','inputmode="decimal"');foreach(['labor_cost'=>'دستمزد قابل انتقال','overhead_cost'=>'سربار قابل انتقال','abnormal_cost'=>'هزینه ضایعات غیرعادی'] as $key=>$label)self::input($key,$label,'0','text','inputmode="decimal"');self::input('reason','دلیل انحراف مقدار یا ضایعات','','text','maxlength="300"'); ?><button type="submit" class="btn btn-primary">تکمیل تولید و ثبت محصول</button></form></section><?php endif; ?>
<?php if($o['status']!=='void'&&Ctx::can('production.delete')): ?><section class="erp-card erp-no-print"><h3>ابطال کنترل‌شده</h3><p>ابطال مواد، محصول و اسناد را یکجا برمی‌گرداند؛ پس از گردش وابسته یا بسته‌شدن دوره، ابطال مستقیم مجاز نیست.</p><form method="post" class="erp-form"><?php self::form('module_production_void',$cid,'production_order',$o['id']); ?><input type="hidden" name="revision" value="<?php echo (int)$o['revision']; ?>"><?php self::input('reason','دلیل ابطال','','text','required minlength="5" maxlength="300"'); ?><button type="submit" class="btn btn-outline">ابطال دستور تولید</button></form></section><?php endif; ?>
<p class="erp-no-print"><a href="<?php echo esc_url(agah_erp_url(['c'=>$cid,'p'=>'production_orders'])); ?>">بازگشت به دستورهای تولید</a></p>
